from app.core.resources import display_rows

"""Payments endpoints and their PostgreSQL queries."""

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.core import sql_queries as sql
from app.core.resources import staff_only
from app.core.security import require

from .service import Service

TABLE = "payments"
router = APIRouter(prefix="/payments", tags=["Payments"])


# --- PostgreSQL queries for this screen (generated by tools/generate_module_sql.py from the
# live table definitions; regenerate after schema migrations). Values are bound as %(name)s
# parameters, never formatted into the text; app.core.sql_queries runs these statements and
# keeps custom fields (record_extras) with each record. Table names resolve through the
# connection's search_path (EDUNEXA_DB_SCHEMA).

LIST_SQL = """
SELECT t.code,
       t.student_code,
       t.amount,
       t.currency,
       t.paid_on,
       t.method,
       t.transaction_reference,
       t.status,
       t.idempotency_key,
       t.request,
       x.data AS extras
FROM payments AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'payments' AND x.record_code = t.code
ORDER BY t.code
"""

GET_SQL = """
SELECT t.code,
       t.student_code,
       t.amount,
       t.currency,
       t.paid_on,
       t.method,
       t.transaction_reference,
       t.status,
       t.idempotency_key,
       t.request,
       x.data AS extras
FROM payments AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'payments' AND x.record_code = t.code
WHERE t.code = %(code)s
"""

INSERT_SQL = """
INSERT INTO payments (
    code,
    student_code,
    amount,
    currency,
    paid_on,
    method,
    transaction_reference,
    status,
    idempotency_key,
    request
)
VALUES (
    %(code)s,
    %(student_code)s,
    %(amount)s,
    %(currency)s,
    %(paid_on)s,
    %(method)s,
    %(transaction_reference)s,
    %(status)s,
    %(idempotency_key)s,
    %(request)s
)
"""

UPDATE_SQL = """
UPDATE payments
SET student_code = %(student_code)s,
    amount = %(amount)s,
    currency = %(currency)s,
    paid_on = %(paid_on)s,
    method = %(method)s,
    transaction_reference = %(transaction_reference)s,
    status = %(status)s,
    idempotency_key = %(idempotency_key)s,
    request = %(request)s
WHERE code = %(code)s
"""

DELETE_SQL = """
DELETE FROM payments
WHERE code = %(code)s
"""

REFERENCED_BY_SQL = """
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM payment_allocations WHERE payment_code = %(code)s) THEN 'payment_allocations'
    WHEN EXISTS (SELECT 1 FROM payment_gateway_orders WHERE payment_code = %(code)s) THEN 'payment_gateway_orders'
    WHEN EXISTS (SELECT 1 FROM receipts WHERE payment_code = %(code)s) THEN 'receipts'
    WHEN EXISTS (SELECT 1 FROM refunds WHERE payment_code = %(code)s) THEN 'refunds'
END AS referenced_by
"""
# --- end of generated SQL


def query_list(data):
    return sql.fetch_all(data, TABLE, LIST_SQL)


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = display_rows(data, TABLE, query_list(data))
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    return query_get(request.app.state.store.snapshot(), code)
